function IdolLive3D_InteractiveManager:__init()
    self.soundDatas = {}
    self.registSoundsStartTime = 0
    self.controller = nil
    self.longFrameCount = 0 -- 只在进入深度互动时才被清零
    self.frameCount = 999 -- 一开始不要为0, 不然会触发 init idle state 的重复播放
    self.isInit = false
end


function IdolLive3D_InteractiveManager:__delete()
end



function IdolLive3D_InteractiveManager:InitBaseParams()

    self.baseJson = self.idolLive3D_Main.baseJson

    self.idleSwitchData = self.baseJson.idleSwitchData
    self.idleSwitchData.cachedTargetIdleType = nil -- 暂存外部输入的想要用按钮 切去的 idle type, 目的是延迟 切换时间点; 平时此值始终为 nil
end




function IdolLive3D_InteractiveManager:Init(main_, runtimeRootTF_, idolLive3D_CameraEnv_, lookAtIK_, roleAnimator_, timelineTFMaps_, superTimelineTFMaps_, simpleFxTFMaps_, allResources_)
    KTool.SetActive(self.controller.gameObject, true);    
    assert( isNotNull(runtimeRootTF_) )

    self.idolLive3D_Main = main_
    self.lookAtIK = lookAtIK_

    -- must after Awake()
    ---@type UnityEngine.Camera
    self.mainCamera = IdolLive3D_Utils.GetMainCamera()
    assert( self.mainCamera )

    ---
    self.idolLive3D_CameraEnv = idolLive3D_CameraEnv_
    self.roleAnimator = roleAnimator_
    self.roleGO = self.roleAnimator.gameObject
    assert( self.idolLive3D_Main and self.idolLive3D_CameraEnv )

    self:InitBaseParams()

    -- 存储每个播放的 interactiveState
    self.interactiveStateQueueMaxNum = 100
    self.interactiveStateQueue = Queue.New( self.interactiveStateQueueMaxNum ) 
    ---
    self.allResources = allResources_

    ---
    local idleSwitch = self.baseJson.data.idleSwitch
    if self.baseJson:IsIdleSwitchByButton() or self.baseJson:IsIdleSwitchSupportFromSuperTimeline() then
        self.fullScreenFXEnv = self.allResources.fullScreenFXEnvs[idleSwitch.fullScreenFXKey]
        if isNull(self.fullScreenFXEnv) then 
            printError("json 文件异常, 未找到 fullScreenFX")
            return
        end     
    else 
        self.fullScreenFXEnv = nil
    end 
    

    ----
    self.spacialState = nil -- 默认不在任何 spacial 交互区间内
    self.freeSoundState = nil -- 默认不在任何 freeSound 交互区间内
    self.cachedIdleState = self.baseJson.defaultInitIdleState  -- 确定要去的 idle state, 但本帧不见得就真的到那个 idle state 了, 有可能正在播放 100->200, 200->100 转场动画中, 此时需使用 currentPlayingIdleState
    self.currentPlayingIdleState = nil -- ("几乎"每帧查询), 当前帧正在播放的 idle state, 不为 idle 状态则为 nil

    self.lastFullPathHash = nil
    self.lastIsLookCamera = false -- lookat 系统
    self._workType = WorkType.None -- 角色当前的 互动状态类型


    self:_InitTimelineStates( checkTable(timelineTFMaps_) )
    self:_InitSuperTimelineStates( checkTable(superTimelineTFMaps_), runtimeRootTF_ )
    self:_InitSimpleFXs( checkTable(simpleFxTFMaps_) )

    -----
    if self.events then
        CfUtils.EventsUndecorated(self.events)
    end
    self.events = CfUtils.EventsDecorated({
        [IdolLive3D_States.EventSwitchIdleToOth] = function()
            self:CallIdleSwitchByButton()
        end,
        [IdolLive3D_States.EventNewInteractiveState] = function()
            --printError( "add to queue: " .. tostring(iState.name) )
        end,
        [IdolLive3D_States.EventSimpleTapInAnyTime] = function()
            --printError( "tap:" .. tostring(idStr_) )
        end,    
        [IdolLive3D_States.EventVirtualSimpleTap] = function(touchKey_)
            self:OnVirtualSimpleTap(touchKey_)
        end,  
        [Constants.EventNames.Live3DIsInTimelineState] = function(isInTimeline_) -- 从 timeline 返回时:
            if isInTimeline_ == false then 
                self:AddToQueue(self.cachedIdleState)
            end 
        end
    })

    -- 配置 LookAtIK 参数:
    self:Update_LookAtIKParams()

    ---
    self.isInit = true
end



function IdolLive3D_InteractiveManager:BindSimpleTap( idolLive3D_Input_ ) 
    idolLive3D_Input_:Add_OnSimpleTapCallBack( function(gesture_)
        self:OnSimpleTap(gesture_)
    end )
end



function IdolLive3D_InteractiveManager:OnDestroy()

    if self.events then
        CfUtils.EventsUndecorated(self.events)
    end

    IdolLive3D_Utils.StopCoroutine(self.co_1)
    self.co_1 = nil

    -- 确保在 释放 self.co_1 之后, 以保证先删协程, 后删 go:
    if isNotNull(self.fullScreenFXEnv) then 
        self.fullScreenFXEnv:Delete()
    end 

    ---
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
end



-- 外部相应按钮点击, 执行一次 idle 100 <-> 200 切换:
function IdolLive3D_InteractiveManager:CallIdleSwitchByButton()
    if self.baseJson:IsIdleSwitchByButton() == false then
        print("想用 按钮 切换 idle, 但 json 配置中并未支持此功能")
        return
    end
    local currentPlaying_IdleState = self:FindCurrentPlayingIdleState()
    if isNull(currentPlaying_IdleState) then 
        print( "想用 按钮 切换 idle, 但当前不在 idle state" )
        return
    end
    -- printError(" 找到: " .. tostring(currentPlaying_IdleState.name) )
    ---
    if currentPlaying_IdleState.idleType == IdleType.Type_100 then 
        self.idleSwitchData.cachedTargetIdleType = IdleType.Type_200
    elseif currentPlaying_IdleState.idleType == IdleType.Type_200 then 
        self.idleSwitchData.cachedTargetIdleType = IdleType.Type_100
    end 
end



-- 外部调用者不关心 当前是否在 target idle; 可用本函数实现 idle 100->100 的强制切换; 
-- 通常使用本函数来强播一遍 全屏转场特效
function IdolLive3D_InteractiveManager:ForceToTargetIdle( idleType_ )
    if (self.baseJson:IsIdleSwitchByButton() or self.baseJson:IsIdleSwitchSupportFromSuperTimeline()) == false then
        print("既没开启 按钮切换, 也没开启 SuperTimeline 进入, 这样无法执行 强转idle")
        return
    end
    local currentPlaying_IdleState = self:FindCurrentPlayingIdleState()
    if isNull(currentPlaying_IdleState) then 
        print( "想用 按钮 切换 idle, 但当前不在 idle state" )
        return
    end
    -- printError(" 找到: " .. tostring(currentPlaying_IdleState.name) )
    assert( idleType_ == IdleType.Type_100 or idleType_ == IdleType.Type_200 )
    self.idleSwitchData.cachedTargetIdleType = idleType_
end



-- ============================= timeline States ==================================

function IdolLive3D_InteractiveManager:_InitTimelineStates( timelineTFMaps_ )
    if table.count(timelineTFMaps_) == 0 then 
        return
    end 

    self.timelineStateEnvMaps = {}
    for name,tf in pairs(timelineTFMaps_) do 
        local stateEnv = IdolLive3D_TimeLineState.New( "0", self.roleAnimator, tf )

        local timelineJson = self.baseJson:Find_TimelineState(name)
        assert( isNotNull(timelineJson) )

        stateEnv:BindFirstLoopStopCB(function( playableDirector_, clipId_ )
            stateEnv:Hide()
            self:_OnTimelineStop( playableDirector_, clipId_, timelineJson.easeOutBlendTime )
        end)
        self.timelineStateEnvMaps[name] = stateEnv 
    end 
end


function IdolLive3D_InteractiveManager:_InitSuperTimelineStates( superTimelineTFMaps_, runtimeRootTF_ )
    if table.count(superTimelineTFMaps_) == 0 then 
        return
    end 

    self.superTimelineStateEnvMaps = {}
    for superTimelineName,tfs in pairs(superTimelineTFMaps_) do 
        local superTimelineJson = self.baseJson:Find_SuperTimelineState(superTimelineName)
        assert( isNotNull(superTimelineJson) )
    
        local envTF = IdolLive3D_Utils.LoadPrefabSync( superTimelinePrefabPath, runtimeRootTF_, superTimelineName )--此prefab尺寸很小, 直接同步加载
        envTF.name = "super." .. superTimelineName
        local superEnv = CfUtils.GetLuaScr(envTF, "Game.IdolLive3D.Interactive.IdolLive3D_SuperTimeLineState")
        superEnv:Init( self, self.roleAnimator, tfs, superTimelineJson, Bind(self,self._OnTimelineStop) )

        self.superTimelineStateEnvMaps[superTimelineName] = superEnv
    end 
end



function IdolLive3D_InteractiveManager:_InitSimpleFXs( simpleFxTFMaps_ )
    if table.count(simpleFxTFMaps_) == 0 then 
        return
    end 

    for name,fxTF in pairs(simpleFxTFMaps_) do
        for _,iState in pairs(self.baseJson.data.simpleInteractiveStates) do 
            if iState.name == name then 
                iState.fxTF = fxTF
                KTool.SetActive( fxTF.gameObject, false )
                break
            end 
        end
    end 
end




