---@return table or nil @ 返回 nil 说明没找到 
function IdolLive3D_InteractiveManager:IsAnimatorStateInfoInIdle( shortNameHash )
    for _,tb in pairs(self.baseJson.shortNameHash_idles) do 
        if tb.hash == shortNameHash then 
            return tb.iState
        end 
    end 
    return nil
end



function IdolLive3D_InteractiveManager:FindCurrentPlayingIdleState_ByShortNameHash( shortNameHash )
    for _,tb in pairs(self.baseJson.shortNameHash_idles) do 
        if tb.hash == shortNameHash then 
            return tb.iState
        end 
    end 
    return nil
end


function IdolLive3D_InteractiveManager:FindCurrentPlayingIdleState()
    local animatorStateInfo = self:GetCurrentAnimatorStateInfo() 
    if isNotNull(animatorStateInfo) then 
        return self:FindCurrentPlayingIdleState_ByShortNameHash(animatorStateInfo.shortNameHash)
    else 
        printError("异常, 没拿到 animatorStateInfo")
    end 
    return nil
end



function IdolLive3D_InteractiveManager:FindTgtIdleState( name_ )
    for _,iState in pairs(self.baseJson.idleStates) do 
        if iState.name == name_ then 
            return iState
        end 
    end
    ---
    printError("koko - 没找到 tgt idle state, 参数: " .. tostring(name_))
    return self.baseJson.defaultInitIdleState
end


-- ===============================================================

function IdolLive3D_InteractiveManager:SelfUpdate()
    if self.isInit ~= true or self.idolLive3D_Main.isInit ~= true then
        return
    end

    -- debug:
    if IdolLive3D_Utils.IsEditorPlatform() then
        
        -- 编辑模式下 idle 切换热键:
        if Input.GetKeyDown(KeyCode.Alpha1) then 
            Events.Broadcast(IdolLive3D_States.EventSwitchIdleToOth, nil)
        elseif Input.GetKeyDown(KeyCode.Alpha2) then 
            Events.Broadcast(IdolLive3D_States.EventSwitchIdleToOth, nil)
        elseif Input.GetKeyDown(KeyCode.Alpha3) then
            self:ForceToTargetIdle(IdleType.Type_100)
        elseif Input.GetKeyDown(KeyCode.Alpha4) then 
            self:ForceToTargetIdle(IdleType.Type_200)
        end

        -- 开关 debug UI:
        if Input.GetKeyDown(KeyCode.Alpha0) then 
            Events.Broadcast(IdolLive3D_States.EventShowDebugUI, true) -- 参数无所谓了
        end

    end


    -- ======================================= 正文 ===========================================

    --- 起步阶段
    if self.longFrameCount == 0 then 
        -- !! 为了让 第一帧的 _IntoIdleState() 能执行成功, 未来要改用更好的办法
        --printError("跳过 0 帧")
        self.longFrameCount = self.longFrameCount + 1
        return

    elseif self.longFrameCount == 1 then 
        if isNotNull(self.baseJson.firstTimelineState) then 
            -- 入场自动播放 timeline:

            self.idolLive3D_CameraEnv:OnSwitchIdle(self.cachedIdleState.idleType)

            self:_IntoIdleState( self.cachedIdleState, false ) -- 强播 init idle state
            self:AddToQueue(self.cachedIdleState) -- !! 放在这里会在第一时间塞入一个 idle 进 queue, 然后再塞入一个 timeline 进 queue
            ---
            self:IntoInitTimelineInteractiveState( self.baseJson.firstTimelineState )
        else 
            self.idolLive3D_CameraEnv:OnSwitchIdle(self.cachedIdleState.idleType)

            self:_IntoIdleState( self.cachedIdleState, true ) -- 强播 init idle state
            self:AddToQueue(self.cachedIdleState)
        end
        
    end 
    if self.longFrameCount < 999999 then 
        self.longFrameCount = self.longFrameCount + 1
    end


    --- 播放 动作内音效
    self:UpdateSoundsInsideInteractive() -- !! 未来要改


    local freeCameraSpatialParams = self:_GetFreeCameraSpatialParams()
    if isNull(freeCameraSpatialParams) then 
        return
    end

    --- camera lookat system:
    -- 因为 lookat 的开关涉及 自由相机机位, 所以必须轮询;
    local currentIsLookCamera = IdolLive3D_Utils:IsCameraSpatialParamsInRange( self:Get_LookCameraSpatialRange(), freeCameraSpatialParams, nil ) 
                                    and self:CurrentInteractiveStateIsOpenLookAt()
    local isLookCameraChangeThisFrame = (currentIsLookCamera ~= self.lastIsLookCamera)
    if isLookCameraChangeThisFrame then 
        self.lastIsLookCamera = currentIsLookCamera
        if isNotNull( self.idolLive3D_Main.roleLookAtController ) then
            local roleLookAtController = self.idolLive3D_Main.roleLookAtController
            if currentIsLookCamera == true then 
                print(" 进入 look camera 区 ")
                roleLookAtController.target = self.mainCamera.transform
            else 
                print(" 离开 look camera 区 ")
                roleLookAtController.target = nil
            end 
        end
    end 


    local cameraMode = self.idolLive3D_CameraEnv:GetCameraMode()
    local isInteractiveFreeze = cameraMode == IdolLive3D_States.CameraMode.Freeze and IdolLive3D_States.isSupportInteractiveInFreeze == true
    if not (cameraMode == IdolLive3D_States.CameraMode.FreeManual or isInteractiveFreeze) then 
        return
    end 


    -- 切换 idle
    -- (会打断 freeSound )
    self:_IdleSwitchCheck( freeCameraSpatialParams )


    -- 触发 机位型 交互:
    -- (会打断 freeSound )
    if self._workType ~= WorkType.Interactive then
        local currentSpacialState = self:FindSpacialState( freeCameraSpatialParams ) -- 可能为 nil
        local isSpacialStateChangeThisFrame = (self.spacialState ~= currentSpacialState)
        self.spacialState = currentSpacialState

        if isNotNull(currentSpacialState) and isSpacialStateChangeThisFrame then 
            print("spacial state 发生变化 -> " .. tostring(currentSpacialState.desc) )
            self:IntoInteractiveState( currentSpacialState )
        end 
    end 

    -- 触发 自由音效 (机位触发的):
    -- 当发现 simple/tl动作 的语音没有播完时, 自由音效 无法被触发;
    if self._workType == WorkType.None and IdolLive3D_Sounds:IsAnyVoicePlaying() == false then

        local currentFreeSoundState = self:FindFreeSoundState( freeCameraSpatialParams ) -- 可能为 nil
        local isFreeSoundStateChangeThisFrame = (self.freeSoundState ~= currentFreeSoundState)
        self.freeSoundState = currentFreeSoundState

        if isNotNull(currentFreeSoundState) and isFreeSoundStateChangeThisFrame then 
            print("free sound state 发生变化 -> " .. tostring(currentFreeSoundState.annotation) )
            self:IntoFreeSoundState( currentFreeSoundState )
        end 
    end

    --- 手动从 动作 中回到 idle:
    if self.frameCount < 99999 then
      self.frameCount = self.frameCount + 1
    end
    if self.frameCount == 9 then
        print(" 回归 idle; cachedIdleState = " .. tostring(self.cachedIdleState.actValue) )
        self:SetAnimatorAct( self.cachedIdleState.actValue ) -- !!!
    end 

    ---- 
    -- 当发现 animator 已经进入 idle state 后, 会将 _workType 复位
    local animatorStateInfo = self:GetCurrentAnimatorStateInfo() 
    if isNotNull(animatorStateInfo) then

        if animatorStateInfo.shortNameHash == 0 and self.longFrameCount > 1 then 
            printError( "hash = 0, 可能是 animator controller 丢了; longFrameCount = " .. tostring(self.longFrameCount))
        end

        -- 每帧都要主动计算:
        self.currentPlayingIdleState = self:FindCurrentPlayingIdleState_ByShortNameHash(animatorStateInfo.shortNameHash)

        local isStateChangedThisFrame = animatorStateInfo.fullPathHash ~= self.lastFullPathHash
        self.lastFullPathHash = animatorStateInfo.fullPathHash

        if isStateChangedThisFrame == true then 
            if isNotNull( self:IsAnimatorStateInfoInIdle(animatorStateInfo.shortNameHash) ) then
                if self._workType == WorkType.Interactive then 
                    self._workType = WorkType.None -- 允许触发下一个 互动

                    self:_CheckAndHideSimpleFX() -- !! Must Before AddToQueue()
                    self:AddToQueue(self.cachedIdleState)
                end 
            end
        end 
    else
        printError("异常, 没拿到 animatorStateInfo")
    end
end


-- 点击 模型身上的碰撞体, 触发的实体 touch交互:
function IdolLive3D_InteractiveManager:OnSimpleTap( gesture_ )
    if self.isInit ~= true then
        return
    end
    print( "tap" )
    local tapPos2 = gesture_.startPosition
    local tapPos3 = Vector3( tapPos2.x, tapPos2.y, 0.0 )
    local ray = self.mainCamera:ScreenPointToRay(tapPos3) -- Ray
    ---
    local legalHitInfos = {} -- 所有携带了 ID组件的 trigger 碰撞体信息
    local raycastHits, raycastHitsNum = IdolLive3D_Utils.RaycastNonAlloc( ray.origin, ray.direction, 20.0, collideLayerMask, QueryTriggerInteraction.Collide )
    --printError("hit num = " .. tostring(raycastHitsNum))
    for i=0, raycastHitsNum-1 do 
        local hit = raycastHits[i]
        if isNotNull(hit) and isNotNull( hit.collider) then
            local idComp = KTool.GetComponent(hit.collider.gameObject, typeof(IDComp))
            if isNotNull(idComp) and type(idComp.stringId) == "string" and (#idComp.stringId > 0) then 
                table.insert( legalHitInfos, {distance = hit.distance, idStr = idComp.stringId} )
            end
        end
    end
    ---
    if #legalHitInfos == 0 then 
        Events.Broadcast(IdolLive3D_States.EventSimpleTapInAnyTime, emptySimpleTapName) -- 表示啥也没点到
        return
    end 
    -- 距离由近及远
    table.sort(legalHitInfos, function(a, b)
        return checkNumber(a.distance) < checkNumber(b.distance)
    end)
    local nearestIDStr = legalHitInfos[1].idStr
    if string.isEmpty(nearestIDStr) then 
        Events.Broadcast(IdolLive3D_States.EventSimpleTapInAnyTime, emptySimpleTapName) -- 表示啥也没点到
        return
    end
    ---------------------
    ---
    if IS_REVIEW and nearestIDStr == "Chest" then
        return
    end
    Events.Broadcast(IdolLive3D_States.EventSimpleTapInAnyTime, nearestIDStr) 
    self:_HandleTouch(nearestIDStr)
end


-- 点击 ui按钮, 触发的虚拟 touch交互:
function IdolLive3D_InteractiveManager:OnVirtualSimpleTap( touchKey_ )
    touchKey_ = tostring(touchKey_)
    Events.Broadcast(IdolLive3D_States.EventSimpleTapInAnyTime, touchKey_) 
    self:_HandleTouch(touchKey_)
end



function IdolLive3D_InteractiveManager:_HandleTouch( touchKey_ )
    touchKey_ = tostring(touchKey_)
    --------------------
    local cameraMode = self.idolLive3D_CameraEnv:GetCameraMode()
    local isInteractiveFreeze = cameraMode == IdolLive3D_States.CameraMode.Freeze and IdolLive3D_States.isSupportInteractiveInFreeze == true
    if not (cameraMode == IdolLive3D_States.CameraMode.FreeManual or isInteractiveFreeze) then 
        return
    end 
    -- (允许中断 freeSound)
    if self._workType == WorkType.Interactive then
        return
    end 

    local newState = self:FindTouchState( self:_GetFreeCameraSpatialParams(), touchKey_ )
    if isNotNull(newState) then 
        -- 当角色在 idle 100 <-> 200 间过度时, 此时若触发交互, 动画将无法被播放, 但声音能播出来, 导致异常; 
        -- 此处直接阻止进入交互
        local animatorStateInfo = self:GetCurrentAnimatorStateInfo() 
        if self:IsAnimatorStateInfoInIdle(animatorStateInfo.shortNameHash) == nil then
            print("点击, 但当前尚未进去 idle 状态, 触发失败")
            return
        end
        print("点击 - " .. tostring(newState.desc) )
        self:IntoInteractiveState( newState )
    end
end



function IdolLive3D_InteractiveManager:IsCachedIdleStateIn100() 
    assert( self.cachedIdleState == self.idleSwitchData.idle_100.idleState  or self.cachedIdleState == self.idleSwitchData.idle_200.idleState  )
    return (self.cachedIdleState == self.idleSwitchData.idle_100.idleState )
end 


function IdolLive3D_InteractiveManager:Update_LookAtIKParams() 
    --print("Update_LookAtIKParams")
    -- 配置 LookAtIK 参数:
    if self:IsCachedIdleStateIn100()  then 
        IdolLive3D_Utils.CopyToLookAtIK( self.lookAtIK, self.idleSwitchData.idle_100.lookAtIKParams )
    else 
        IdolLive3D_Utils.CopyToLookAtIK( self.lookAtIK, self.idleSwitchData.idle_200.lookAtIKParams )
    end 
end 



function IdolLive3D_InteractiveManager:Get_LookCameraSpatialRange() 
    if self:IsCachedIdleStateIn100()  then 
        return self.idleSwitchData.idle_100.LookCameraSpatialRange
    else 
        return self.idleSwitchData.idle_200.LookCameraSpatialRange
    end
end 


-- 检查当前 自由轨道相机机位 是否位于 iState_ 的触发区间:
---@return boolean
function IdolLive3D_InteractiveManager:IsFreeTrackCameraInTargetIStateRange( iState_ ) 
    local freeCameraSpatialParams = self:_GetFreeCameraSpatialParams()
    local ret = IdolLive3D_Utils:IsCameraSpatialParamsInRange(iState_.cameraSpatialRange, freeCameraSpatialParams, iState_.compareMode )
    return ret
end


-- ====================================== idle state switch ==================================================


function IdolLive3D_InteractiveManager:_IdleSwitchCheck( freeCameraSpatialParams_ ) 
    if self._workType == WorkType.Interactive then
        return
    end

    if not ( self.baseJson.data.idleSwitch.isNeedIdleSwitch or self.baseJson:IsIdleSwitchSupportFromSuperTimeline() ) then 
        return
    end

    
    if self.baseJson.data.idleSwitch.isNeedIdleSwitch then
        if self.baseJson.data.idleSwitch.idleSwitchMode == IdolLive3D_States.IdleSwitchMode.ByCameraSpacial then
            ---
            local newIdleState = self.baseJson:FindCurrentIdleState( freeCameraSpatialParams_ )
            local isIdleStateChange = self.cachedIdleState ~= newIdleState
            self.cachedIdleState = newIdleState
            if isIdleStateChange then 
                
                -- 本协程存在的目的主要为了将 "idle switch" 和 "new idle" 两个阶段拆分开; 分别 AddToQueue();
                IdolLive3D_Utils.StopCoroutine(self.co_1)
                self.co_1 = cs_coroutine.start(function()
                    --printError("_IdleSwitchCheck - ByCameraSpacial")
                    
                    self:AddToQueue( (newIdleState.idleType == IdleType.Type_100) and self.idleSwitchData.iState_from_200_To_100 or self.idleSwitchData.iState_from_100_To_200 )
                    -- !! 此处暂时不瞬切 rolePos
                    self:_IntoIdleState( newIdleState, true )

                    -- 等待 idle 切换完毕; 只等待有限帧:
                    local isSwitchSuccess = false
                    for i=0, 5000 do
                        local animatorStateInfo = self:GetCurrentAnimatorStateInfo()                    
                        local idle_istate = self:IsAnimatorStateInfoInIdle(animatorStateInfo.shortNameHash)
                        if isNotNull(idle_istate) then 
                            if newIdleState.idleType == IdleType.Type_100 and idle_istate.actValue == 100 then 
                                print( "idle 机位切换: 角色进入 idle 100" )
                                isSwitchSuccess = true
                                break
                            elseif newIdleState.idleType == IdleType.Type_200 and idle_istate.actValue == 200 then
                                print( "idle 机位切换: 角色进入 idle 200" )
                                isSwitchSuccess = true
                                break
                            end
                        end 
                        coroutine.yield(Yielders.EndOfFrame)
                    end
                    if isSwitchSuccess == false then 
                        printError("idle 切换 似乎未正式完成, 请检查")
                    end 
                    ---
                    self:AddToQueue(newIdleState)
                    self:Update_LookAtIKParams()
                end) 
            end 
        else 
            ---
            if isNull(self.idleSwitchData.cachedTargetIdleType) then 
                return
            end 
            ---
            local newIdleState = self.baseJson:IdleType_To_IdleState(self.idleSwitchData.cachedTargetIdleType, true) -- 想要切去的 idle   
            self.idleSwitchData.cachedTargetIdleType = nil -- !! MUST     
            local isIdleStateChange = self.cachedIdleState ~= newIdleState
            self.cachedIdleState = newIdleState
            if isIdleStateChange then 

                IdolLive3D_Utils.StopCoroutine(self.co_1)
                self.co_1 = cs_coroutine.start(function()
                    --printError("_IdleSwitchCheck - ByBtn")

                    self:AddToQueue( (newIdleState.idleType == IdleType.Type_100) and self.idleSwitchData.iState_from_200_To_100 or self.idleSwitchData.iState_from_100_To_200 )

                    cs_coroutine.yield_return( self.fullScreenFXEnv:FadeIn() ) --- 全屏特效 淡入

                    -- 瞬切 相机, rolePos 等:
                    self.idolLive3D_CameraEnv.idolLive3D_Main:OnSwitchIdle(newIdleState.idleType)
                    self.idolLive3D_CameraEnv:OnSwitchIdle(newIdleState.idleType)

                    self:_IntoIdleState( newIdleState, true )

                    -- 等待 idle 切换完毕; 只等待有限帧:
                    local isSwitchSuccess = false
                    for i=0, 5000 do
                        local animatorStateInfo = self:GetCurrentAnimatorStateInfo()                    
                        local idle_istate = self:IsAnimatorStateInfoInIdle(animatorStateInfo.shortNameHash)
                        if isNotNull(idle_istate) then 
                            if newIdleState.idleType == IdleType.Type_100 and idle_istate.actValue == 100 then 
                                print( "idle 按钮切换: 角色进入 idle 100" )
                                isSwitchSuccess = true
                                break
                            elseif newIdleState.idleType == IdleType.Type_200 and idle_istate.actValue == 200 then
                                print( "idle 按钮切换: 角色进入 idle 200" )
                                isSwitchSuccess = true
                                break
                            end
                        end 
                        coroutine.yield(Yielders.EndOfFrame)
                    end
                    if isSwitchSuccess == false then 
                        printError("idle 切换 似乎未正式完成, 请检查")
                    end

                    ---
                    self:Update_LookAtIKParams()
                    self:AddToQueue(newIdleState)
                    cs_coroutine.yield_return( self.fullScreenFXEnv:FadeOut() ) -- 全屏特效 淡出
                end) 

            end
        end
        return -- !! Must
    end


    if self.baseJson:IsIdleSwitchSupportFromSuperTimeline() then

        if isNull(self.idleSwitchData.cachedTargetIdleType) then 
            return
        end 
        ---
        local newIdleState = self.baseJson:IdleType_To_IdleState(self.idleSwitchData.cachedTargetIdleType, true) -- 想要切去的 idle   
        self.idleSwitchData.cachedTargetIdleType = nil -- !! MUST     
        local isIdleStateChange = self.cachedIdleState ~= newIdleState
        self.cachedIdleState = newIdleState

        ------- 并没有切换 idle, 但把这个流程走了一遍 (变相 播放了一次 全屏转场特效) -------
        IdolLive3D_Utils.StopCoroutine(self.co_1)
        self.co_1 = cs_coroutine.start(function()
            --printError("_IdleSwitchCheck - By SuperTimeline")

            if isIdleStateChange then 
                self:AddToQueue( (newIdleState.idleType == IdleType.Type_100) and self.idleSwitchData.iState_from_200_To_100 or self.idleSwitchData.iState_from_100_To_200 )
            else 
                self:AddToQueue( (newIdleState.idleType == IdleType.Type_100) and self.idleSwitchData.iState_from_100_To_100 or self.idleSwitchData.iState_from_200_To_200 )
            end 

            cs_coroutine.yield_return( self.fullScreenFXEnv:FadeIn() ) --- 全屏特效 淡入

            -- 瞬切 相机, rolePos 等:
            self.idolLive3D_CameraEnv.idolLive3D_Main:OnSwitchIdle(newIdleState.idleType)
            self.idolLive3D_CameraEnv:OnSwitchIdle(newIdleState.idleType)

            self:_IntoIdleState( newIdleState, true )

            -- 等待 idle 切换完毕; 只等待有限帧:
            local isSwitchSuccess = false
            for i=0, 5000 do
                local animatorStateInfo = self:GetCurrentAnimatorStateInfo()                    
                local idle_istate = self:IsAnimatorStateInfoInIdle(animatorStateInfo.shortNameHash)
                if isNotNull(idle_istate) then 
                    if newIdleState.idleType == IdleType.Type_100 and idle_istate.actValue == 100 then 
                        print( "idle 按钮切换: 角色进入 idle 100" )
                        isSwitchSuccess = true
                        break
                    elseif newIdleState.idleType == IdleType.Type_200 and idle_istate.actValue == 200 then
                        print( "idle 按钮切换: 角色进入 idle 200" )
                        isSwitchSuccess = true
                        break
                    end
                end 
                coroutine.yield(Yielders.EndOfFrame)
            end
            if isSwitchSuccess == false then 
                printError("idle 切换 似乎未正式完成, 请检查")
            end
            ---
            self:Update_LookAtIKParams()
            self:AddToQueue(newIdleState)
            cs_coroutine.yield_return( self.fullScreenFXEnv:FadeOut() ) -- 全屏特效 淡出
        end) 
    end
    
end


