---@param playableDirector_ UnityEngine.Playables.PlayableDirector
---@param timelineClipId_ number 
---@param blendTime_ number
function IdolLive3D_InteractiveManager:_OnTimelineStop(playableDirector_, timelineClipId_, blendTime_) 
    if type(blendTime_) ~= "number" or blendTime_ < 0.0 then 
        printError("参数 blendTime_ 异常: " .. tostring(blendTime_))
        blendTime_ = 0
    end 
    IdolLive3D_Utils.SetVCamBlendMode( CinemachineBlendDefinition.Style.EaseInOut, blendTime_ )
    self.idolLive3D_CameraEnv:SwitchToCameraMode_FreeManual( blendTime_ )
end




-- =================================== Into State =====================================================

-- 进入交互状态
---@return boolean @ 是否成功进入目标 state
function IdolLive3D_InteractiveManager:IntoInteractiveState( interactiveState_ )
    if type(interactiveState_) ~= "table" then 
        printError("koko- 参数异常")
        return false
    end 

    -- 外部已经做过一层屏蔽了, 此处这个检测有点多余
    if self._workType == WorkType.Interactive then
        print("koko - 放弃进入状态: " .. tostring(interactiveState_.desc) .. "; isWorking = " .. tostring(self._workType)  )
        return false
    end     

    if interactiveState_.stateType == StateType.Simple then 

        local isSetSuccess = self:SetAnimatorAct( interactiveState_.actValue )
        if isSetSuccess ~= true then 
            return false
        end 

        -- sounds: 
        self:RegistSounds( interactiveState_, true )

        -- 播放 fx: (如果有)
        if isNotNull(interactiveState_.fxTF) then 
            KTool.SetActive( interactiveState_.fxTF.gameObject, true )
        end 

        self:BroadcastPlayAction(interactiveState_)

        interactiveState_.playTimes = interactiveState_.playTimes + 1
        --print("simple play times = " .. tostring(interactiveState_.playTimes))
        self:AddToQueue(interactiveState_)

        --print( "正式切入: " .. tostring(interactiveState_.desc) )
        self.frameCount = 0 -- 重置计数器
        self._workType = WorkType.Interactive

        self:PlayVideoSubtitle(interactiveState_.videoSubtitle) -- 播放字幕
        
        return true

    elseif interactiveState_.stateType == StateType.Timeline then

        local cameraMode = self.idolLive3D_CameraEnv:GetCameraMode()
        if cameraMode == IdolLive3D_States.CameraMode.Freeze then       -- !!! Freeze 模式暂不支持触发 timeline
            return false
        end 

        self:_Into_TimelineState( interactiveState_ )        
        return true

    elseif interactiveState_.stateType == StateType.SuperTimeline then

        local cameraMode = self.idolLive3D_CameraEnv:GetCameraMode()
        if cameraMode == IdolLive3D_States.CameraMode.Freeze then       -- !!! Freeze 模式暂不支持触发 superTimeline
            return false
        end 

        self:_Into_SuperTimelineState(interactiveState_)        
        return true
    else
        printError(" 目标 state 的 stateType 类型异常: " .. tostring(interactiveState_.desc) )
        return false
    end     
end





-- 进入 入场第一个 timeline / superTimeline 交互状态:
---@return boolean @ 是否成功进入目标 state
function IdolLive3D_InteractiveManager:IntoInitTimelineInteractiveState( interactiveState_ )
    if type(interactiveState_) ~= "table" then 
        printError("koko- 参数异常")
        return false
    end 
    
    if interactiveState_.stateType == StateType.Timeline then 
        self:_Into_TimelineState( interactiveState_, 0 )

    elseif interactiveState_.stateType == StateType.SuperTimeline then
        self:_Into_SuperTimelineState(interactiveState_)

    else 
        printError("interactiveState_ 异常, stateType = " .. tostring(interactiveState_.stateType))
        return false
    end
    return true
end

