function IdolLive3D_InteractiveManager:_Into_TimelineState( interactiveState_, blendTime_ )

    local timelineStateEnv = self.timelineStateEnvMaps[interactiveState_.name]
    if isNull(timelineStateEnv) then 
        printError("没找到 timelineStateEnv")
        return false
    end 
    -- sounds: 
    self:RegistSounds( interactiveState_, true )

    self:BroadcastPlayAction(interactiveState_)

    interactiveState_.playTimes = interactiveState_.playTimes + 1
    --print("timeline play times = " .. tostring(interactiveState_.playTimes))
    self:AddToQueue(interactiveState_)

    self:PlayVideoSubtitle(interactiveState_.videoSubtitle) -- 播放字幕

    self:BeginTimeline_SimpleBlendMode( timelineStateEnv, interactiveState_, blendTime_ )
    -- !!! 此处是否有必要改写 _workType ???
end


function IdolLive3D_InteractiveManager:_Into_SuperTimelineState( interactiveState_ )

    local superTimelineStateEnv = self.superTimelineStateEnvMaps[interactiveState_.name]
    if isNull(superTimelineStateEnv) then 
        printError("没找到 superTimelineStateEnv")
        return false
    end 
    -- IdolLive3D_Utils.SetVCamBlendMode( CinemachineBlendDefinition.Style.EaseInOut, 0 ) -- 会被后续同函数调用覆盖

    self:BroadcastPlayAction(interactiveState_)
    interactiveState_.playTimes = interactiveState_.playTimes + 1
    self:AddToQueue(interactiveState_)

    superTimelineStateEnv:Play()

    -- !!! 此处是否有必要改写 _workType ???
end




