-- 进入交互状态
---@return boolean @ 是否成功进入目标 state
function IdolLive3D_InteractiveManager:IntoFreeSoundState( interactiveState_ )
    if type(interactiveState_) ~= "table" then 
        printError("koko- 参数异常")
        return false
    end 
    -- sounds: 
    self:AddToQueue(interactiveState_)

    self:PlayVideoSubtitle(interactiveState_.videoSubtitle) -- 播放字幕

    self:RegistSounds( interactiveState_, false )
    self._workType = WorkType.FreeSound
    return true   
end



---@return boolean
function IdolLive3D_InteractiveManager:_IntoIdleState( interactiveState_, isPlaySounds_ )
    if type(interactiveState_) ~= "table" then 
        printError("koko- 参数异常")
        return false
    end 
    local isSetSuccess = self:SetAnimatorAct( interactiveState_.actValue )
    if isSetSuccess == true then 

        if isPlaySounds_ == true and self:IsPlayTimesOverflow(interactiveState_) == false then 
            self:PlayVideoSubtitle(interactiveState_.videoSubtitle) -- 播放字幕
            self:RegistSounds( interactiveState_, false )
        end

        interactiveState_.playTimes = interactiveState_.playTimes + 1

        print( "正式切入: " .. tostring(interactiveState_.desc) )
        return true
    else 
        return false
    end 
end


