-- iState 的播放次数是否满了
function IdolLive3D_InteractiveManager:IsPlayTimesOverflow( interactiveState_ )
    if type(interactiveState_.maxPlayTimes) ~= "number" then 
        interactiveState_.maxPlayTimes = -1
    end
    -- 小于 1 的值都表示 无限次的意思
    if interactiveState_.maxPlayTimes < 1 or interactiveState_.playTimes < interactiveState_.maxPlayTimes then 
        return false
    end 
    return true
end


function IdolLive3D_InteractiveManager:_GetFreeCameraSpatialParams()
    local params = isNotNull(self.idolLive3D_CameraEnv) and self.idolLive3D_CameraEnv:GetFreeCameraSpatialParams() or nil
    if isNull(params) then 
        printError("koko 获取 freeCameraSpatialParams 失败")
    end 
    return params
