function IdolLive3D_InteractiveManager:FindTouchState( cameraSpatialParams_, tgtStr_ )
    if type(tgtStr_) ~= "string" or (#tgtStr_ == 0) then
        printError("koko - 碰撞体 Id.stringId 数据疑似异常 ") 
        return nil
    end
    if isNull(cameraSpatialParams_) then 
        printError("koko - 参数 cameraSpatialParams_ 为空")
        return nil
    end 
    ---
    for _,iState in pairs(self.baseJson.InteractiveStates) do 
        if      string.lower(iState.desc) == string.lower(tgtStr_) 
            and iState.interactiveType == InteractiveType.Touch 
            and iState.stateType ~= StateType.Idle
            and IdolLive3D_Utils:IsCameraSpatialParamsInRange(iState.cameraSpatialRange, cameraSpatialParams_, iState.compareMode )
            --and iState.fromName == self.cachedIdleState.name
            and ( isNotNull(self.currentPlayingIdleState) and iState.fromName == self.currentPlayingIdleState.name )
            and self:IsPlayTimesOverflow(iState) == false
        then 
            return iState
        end 
    end 
    ---
    return nil
end




