-- ================================================ queue ========================================================== 


-- !! 务必保证本函数能忠实地记录 istate 的切换;
---@param iState table 
---@param superTimelineClipInfo_ table | nil
function IdolLive3D_InteractiveManager:AddToQueue( iState, superTimelineClipInfo_ )
    
    self:_AddToQueueLast( { iStateName = iState.name} )
    --- 

    if isNull(superTimelineClipInfo_) then
        -- ===== new iState =====
        print( "add queue: - iState: " .. tostring(iState.name) )
        Events.Broadcast(IdolLive3D_States.EventNewInteractiveState, iState)

        --- 特殊阶段要锁玩家操作:
        -- (timeline 阶段的锁被放到别处了)
        if (iState.stateType == IdolLive3D_States.InteractiveStateType.IdleSwitch) and (self.baseJson:IsIdleSwitchByButton() or self.baseJson:IsIdleSwitchSupportFromSuperTimeline()) then 
            IdolLive3D_States.isForbidPlayerSwipeAndPinch = true
        else 
            IdolLive3D_States.isForbidPlayerSwipeAndPinch = false
        end 
    else 
        -- ===== new superTimeline Clip =====
        local clipId = superTimelineClipInfo_.clipId -- string
        local clipJson = superTimelineClipInfo_.clipJson
        print( "add queue: - clip: " .. tostring(iState.name) .. ", clip: " .. tostring(clipId) )

        self:_AddToQueueLast( { iStateName = iState.name, clipInfo = superTimelineClipInfo_ } )
    end
end


function IdolLive3D_InteractiveManager:_AddToQueueLast(ent_) 
    while self.interactiveStateQueue:Count() >= self.interactiveStateQueueMaxNum do 
        self.interactiveStateQueue:RemoveFirst()
    end 
    self.interactiveStateQueue:AddLast( ent_ )
end



function IdolLive3D_InteractiveManager:PeekLastInteractiveStateFromQueue()

    if self.interactiveStateQueue:Count() == 0 then 
        printError("queue 为 空, 代码逻辑异常")
        return nil
    end 
    ---
    local ent = self.interactiveStateQueue:PeekLast() -- table 
    local name = ent.iStateName
    local iState = self.baseJson.name_to_InteractiveStates[name]
    if isNull(iState) then 
        printError( "异常, 反解表 name_to_InteractiveStates 中没找到元素: " .. tostring(name) )
    end 
    ent.iState = iState
    return ent
end 



function IdolLive3D_InteractiveManager:IsInIdleState()
    local lastState = self:PeekLastInteractiveStateFromQueue().iState
    return (lastState.actValue == 100 or lastState.actValue == 200)
end


-- ================================================


function IdolLive3D_InteractiveManager:CurrentInteractiveStateIsOpenLookAt()
    local queEnt = self:PeekLastInteractiveStateFromQueue()
    local iState = queEnt.iState
    if isNull(iState) then 
        return true
    end 
    ---
    if (iState.stateType == StateType.Simple or iState.stateType == StateType.Timeline) and iState.isCloseLookAt == true then 
        return false
    end

    if iState.stateType == StateType.SuperTimeline and queEnt.clipInfo.clipJson.isCloseLookAt == true then 
        if isNotNull(queEnt.clipInfo) and isNotNull(queEnt.clipInfo.clipJson) and isNotNull(queEnt.clipInfo.clipJson.isCloseLookAt) then 
            return false
        else 
            printError("queue 数据缺失, iState: " .. tostring(queEnt.iStateName))
        end
    end 
    
    return true
end


-- 在一个 simple iState 播放完毕后, 检查它是否包含 fx, 如果有, 将 fx 关闭
function IdolLive3D_InteractiveManager:_CheckAndHideSimpleFX() 

    local queEnt = self:PeekLastInteractiveStateFromQueue() 
    local iState = queEnt.iState
    if iState.stateType == StateType.Simple and isNotNull(iState.fxTF) then 
        KTool.SetActive( iState.fxTF.gameObject, false )
    end 
end


-- 播放字幕
function IdolLive3D_InteractiveManager:PlayVideoSubtitle( videoSubtitle ) 
    --printError("播放字幕 - " .. tostring(videoSubtitle.id))
    if string.isEmpty(videoSubtitle.id) == false and type(videoSubtitle.waitTime) == "number" then 
        --printError( "发生 字幕请求: " .. tostring(videoSubtitle.id)  )
        Events.Broadcast(IdolLive3D_States.EventPlayVideoSubtitle, videoSubtitle.id, videoSubtitle.waitTime)
    end 
end 






return IdolLive3D_InteractiveManager
